import java.util.*;

public class CollectionsExample {
    record Attempt(String student, int score) {}

    public static void main(String[] args) {
        List<Attempt> attempts = List.of(
                new Attempt("Avery", 92), new Attempt("Jordan", 85), new Attempt("Avery", 95),
                new Attempt("Sam", 76), new Attempt("Jordan", 88), new Attempt("Sam", 92));

        // List: keeps every score, duplicates included, in insertion order until sorted
        List<Integer> scores = new ArrayList<>();
        for (Attempt a : attempts) {
            scores.add(a.score());
        }
        Collections.sort(scores);

        // Set: a TreeSet drops duplicates and keeps the rest sorted
        Set<Integer> uniqueScores = new TreeSet<>(scores);

        // Map: TreeMap keeps student names sorted; merge combines old and new values
        Map<String, Integer> attemptCount = new TreeMap<>();
        Map<String, Integer> bestScore = new TreeMap<>();
        for (Attempt a : attempts) {
            attemptCount.merge(a.student(), 1, Integer::sum);
            bestScore.merge(a.student(), a.score(), Math::max);
        }

        // Deque: ArrayDeque used as a FIFO queue of students waiting for feedback
        Deque<String> feedbackQueue = new ArrayDeque<>(bestScore.keySet());
        String first = feedbackQueue.pollFirst();

        System.out.println("Sorted scores: " + scores);
        System.out.println("Unique scores: " + uniqueScores);
        System.out.println("Attempts per student: " + attemptCount);
        System.out.println("Best score by student: " + bestScore);
        System.out.println("Feedback first for: " + first + ", still waiting: " + feedbackQueue);
    }
}

