#include <algorithm>
#include <deque>
#include <iostream>
#include <map>
#include <set>
#include <string>
#include <vector>

struct Attempt {
    std::string student;
    int score;
};

// Print containers the way Java's toString does: [a, b] and {k=v, k=v}
template <typename C>
std::string listStr(const C& c) {
    std::string s = "[";
    bool first = true;
    for (const auto& x : c) {
        if (!first) s += ", ";
        if constexpr (std::is_same_v<std::decay_t<decltype(x)>, std::string>) s += x;
        else s += std::to_string(x);
        first = false;
    }
    return s + "]";
}

std::string mapStr(const std::map<std::string, int>& m) {
    std::string s = "{";
    bool first = true;
    for (const auto& [k, v] : m) {
        if (!first) s += ", ";
        s += k + "=" + std::to_string(v);
        first = false;
    }
    return s + "}";
}

int main() {
    const std::vector<Attempt> attempts = {
        {"Avery", 92}, {"Jordan", 85}, {"Avery", 95}, {"Sam", 76}, {"Jordan", 88}, {"Sam", 92}};

    // vector: keeps every score, duplicates included
    std::vector<int> scores;
    for (const auto& a : attempts) scores.push_back(a.score);
    std::sort(scores.begin(), scores.end());

    // std::set is a sorted tree, like TreeSet
    std::set<int> uniqueScores(scores.begin(), scores.end());

    // std::map is a sorted tree, like TreeMap; operator[] inserts 0 for a new key
    std::map<std::string, int> attemptCount, bestScore;
    for (const auto& a : attempts) {
        attemptCount[a.student] += 1;
        auto [it, inserted] = bestScore.try_emplace(a.student, a.score);
        if (!inserted) it->second = std::max(it->second, a.score);
    }

    // std::deque as a FIFO queue
    std::deque<std::string> feedbackQueue;
    for (const auto& [name, best] : bestScore) feedbackQueue.push_back(name);
    std::string first = feedbackQueue.front();
    feedbackQueue.pop_front();

    std::cout << "Sorted scores: " << listStr(scores) << "\n";
    std::cout << "Unique scores: " << listStr(uniqueScores) << "\n";
    std::cout << "Attempts per student: " << mapStr(attemptCount) << "\n";
    std::cout << "Best score by student: " << mapStr(bestScore) << "\n";
    std::cout << "Feedback first for: " << first << ", still waiting: " << listStr(feedbackQueue) << "\n";
}

