import java.util.ArrayList;
import java.util.List;

public class ArrayListOperations {
    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<>();
        for (int x : new int[] {10, 20, 30, 40}) {
            nums.add(x); // amortized O(1): appends at the end of the backing array
        }
        System.out.println("after add x4:        " + nums);

        nums.add(0, 5); // O(n): every existing element shifts one slot right
        System.out.println("after add(0, 5):     " + nums);

        System.out.println("get(2):              " + nums.get(2)); // O(1) random access

        nums.set(2, 25); // replaces in place, size unchanged
        System.out.println("after set(2, 25):    " + nums);

        nums.remove(1); // int argument -> remove(int index)
        System.out.println("after remove(1):     " + nums);

        nums.remove(Integer.valueOf(30)); // Integer argument -> remove(Object value)
        System.out.println("after remove(30 obj): " + nums);

        System.out.println("contains(25): " + nums.contains(25) + ", indexOf(40): " + nums.indexOf(40)
                + ", size: " + nums.size());
    }
}

