#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

// std::vector is C++'s ArrayList: a growable contiguous array
std::string str(const std::vector<int>& v) {
    std::string s = "[";
    for (size_t i = 0; i < v.size(); ++i) s += (i ? ", " : "") + std::to_string(v[i]);
    return s + "]";
}

int main() {
    std::vector<int> nums;
    for (int x : {10, 20, 30, 40}) {
        nums.push_back(x); // amortized O(1)
    }
    std::cout << "after add x4:        " << str(nums) << "\n";

    nums.insert(nums.begin(), 5); // O(n): elements shift right
    std::cout << "after add(0, 5):     " << str(nums) << "\n";

    std::cout << "get(2):              " << nums[2] << "\n";

    nums[2] = 25;
    std::cout << "after set(2, 25):    " << str(nums) << "\n";

    nums.erase(nums.begin() + 1); // remove by index
    std::cout << "after remove(1):     " << str(nums) << "\n";

    // remove by value: find it first, then erase that position
    auto it = std::find(nums.begin(), nums.end(), 30);
    if (it != nums.end()) nums.erase(it);
    std::cout << "after remove(30 obj): " << str(nums) << "\n";

    bool contains = std::find(nums.begin(), nums.end(), 25) != nums.end();
    long index = std::find(nums.begin(), nums.end(), 40) - nums.begin();
    std::cout << std::boolalpha << "contains(25): " << contains << ", indexOf(40): " << index
              << ", size: " << nums.size() << "\n";
}

