import java.util.*;

public class HashMapWordCount {
    public static void main(String[] args) {
        String text = "to be or not to be that is the question";
        String[] words = text.split(" ");

        // Frequency count: merge inserts 1 for a new key, otherwise adds 1 to the old value
        Map<String, Integer> counts = new HashMap<>();
        for (String w : words) {
            counts.merge(w, 1, Integer::sum);
        }
        // HashMap has no order guarantee, so copy into a TreeMap to print sorted keys
        System.out.println("counts: " + new TreeMap<>(counts));

        System.out.println("get(\"to\"): " + counts.get("to"));
        System.out.println("get(\"java\"): " + counts.get("java")); // missing key -> null
        System.out.println("getOrDefault(\"java\", 0): " + counts.getOrDefault("java", 0));

        // put returns the previous value (or null) and overwrites it
        Integer previous = counts.put("be", 10);
        System.out.println("put(\"be\", 10) replaced: " + previous);

        // Grouping: computeIfAbsent creates the list the first time a length is seen
        Map<Integer, List<String>> byLength = new TreeMap<>();
        for (String w : new TreeSet<>(counts.keySet())) {
            byLength.computeIfAbsent(w.length(), k -> new ArrayList<>()).add(w);
        }
        System.out.println("words by length: " + byLength);
        System.out.println("distinct words: " + counts.size());
    }
}

