int main() {
    std::string text = "to be or not to be that is the question";

    // unordered_map is the hash table (like HashMap); operator[] inserts 0 for a new key
    std::unordered_map<std::string, int> counts;
    std::istringstream in(text);
    std::string w;
    while (in >> w) counts[w] += 1;

    // Hash order is unspecified, so copy into an ordered std::map before printing
    std::map<std::string, int> sorted(counts.begin(), counts.end());
    std::cout << "counts: {";
    bool first = true;
    for (const auto& [k, v] : sorted) {
        std::cout << (first ? "" : ", ") << k << "=" << v;
        first = false;
    }
    std::cout << "}\n";

    std::cout << "get(\"to\"): " << counts.at("to") << "\n";
    // find() looks up without inserting (operator[] would insert a 0)
    auto it = counts.find("java");
    std::cout << "get(\"java\"): " << (it == counts.end() ? "null" : std::to_string(it->second)) << "\n";
    std::cout << "getOrDefault(\"java\", 0): " << (it == counts.end() ? 0 : it->second) << "\n";

    int previous = counts["be"];
    counts["be"] = 10;
    std::cout << "put(\"be\", 10) replaced: " << previous << "\n";

    // Grouping: operator[] creates the empty vector the first time a length is seen
    std::map<size_t, std::vector<std::string>> byLength;
    for (const auto& [word, count] : sorted) byLength[word.size()].push_back(word);
    std::cout << "words by length: {";
    first = true;
    for (const auto& [len, group] : byLength) {
        std::cout << (first ? "" : ", ") << len << "=[";
        for (size_t i = 0; i < group.size(); ++i) std::cout << (i ? ", " : "") << group[i];
        std::cout << "]";
        first = false;
    }
    std::cout << "}\n";
    std::cout << "distinct words: " << counts.size() << "\n";
}

