import java.util.*;

public class HashSetEnrollment {
    // HashSet iteration order is unspecified; print through a TreeSet to get sorted output
    static String sorted(Set<String> set) {
        return new TreeSet<>(set).toString();
    }

    public static void main(String[] args) {
        Set<String> algorithms = new HashSet<>();
        for (String name : List.of("ana", "ben", "cara", "ana", "dev")) {
            boolean added = algorithms.add(name); // false when the element is already present
            System.out.println("add(" + name + ") -> " + added);
        }
        Set<String> databases = new HashSet<>(List.of("cara", "dev", "eli"));

        System.out.println("algorithms: " + sorted(algorithms) + ", size " + algorithms.size());
        System.out.println("contains(ben): " + algorithms.contains("ben")); // average O(1)

        // Set algebra mutates the receiver, so start from a copy each time
        Set<String> both = new HashSet<>(algorithms);
        both.retainAll(databases); // intersection
        Set<String> either = new HashSet<>(algorithms);
        either.addAll(databases); // union
        Set<String> onlyAlgorithms = new HashSet<>(algorithms);
        onlyAlgorithms.removeAll(databases); // difference

        System.out.println("in both courses: " + sorted(both));
        System.out.println("in either course: " + sorted(either));
        System.out.println("only algorithms: " + sorted(onlyAlgorithms));
    }
}

