#include <iostream>
#include <set>
#include <string>
#include <unordered_set>
#include <vector>

// unordered_set is the hash set; copy into std::set (sorted) for a stable print
std::string sorted(const std::unordered_set<std::string>& s) {
    std::set<std::string> ordered(s.begin(), s.end());
    std::string out = "[";
    bool first = true;
    for (const auto& x : ordered) {
        out += (first ? "" : ", ") + x;
        first = false;
    }
    return out + "]";
}

int main() {
    std::cout << std::boolalpha;
    std::unordered_set<std::string> algorithms;
    for (const std::string name : {"ana", "ben", "cara", "ana", "dev"}) {
        bool added = algorithms.insert(name).second; // .second is false for a duplicate
        std::cout << "add(" << name << ") -> " << added << "\n";
    }
    std::unordered_set<std::string> databases = {"cara", "dev", "eli"};

    std::cout << "algorithms: " << sorted(algorithms) << ", size " << algorithms.size() << "\n";
    std::cout << "contains(ben): " << (algorithms.count("ben") > 0) << "\n";

    std::unordered_set<std::string> both, either = algorithms, onlyAlgorithms;
    for (const auto& x : algorithms) {
        if (databases.count(x)) both.insert(x);
        else onlyAlgorithms.insert(x);
    }
    either.insert(databases.begin(), databases.end());

    std::cout << "in both courses: " << sorted(both) << "\n";
    std::cout << "in either course: " << sorted(either) << "\n";
    std::cout << "only algorithms: " << sorted(onlyAlgorithms) << "\n";
}

