import java.util.Map;
import java.util.TreeMap;

public class TreeMapGradeCutoffs {
    public static void main(String[] args) {
        // Keys are inserted out of order; the red-black tree keeps them sorted
        TreeMap<Integer, String> cutoffs = new TreeMap<>();
        cutoffs.put(80, "B");
        cutoffs.put(0, "F");
        cutoffs.put(90, "A");
        cutoffs.put(60, "D");
        cutoffs.put(70, "C");
        System.out.println("cutoffs: " + cutoffs);
        System.out.println("firstKey: " + cutoffs.firstKey() + ", lastKey: " + cutoffs.lastKey());

        // floorEntry(s) = entry with the greatest key <= s, found in O(log n)
        for (int score : new int[] {59, 60, 85, 100}) {
            Map.Entry<Integer, String> e = cutoffs.floorEntry(score);
            System.out.println("score " + score + " -> floorKey " + e.getKey() + " -> grade " + e.getValue());
        }

        System.out.println("ceilingKey(61): " + cutoffs.ceilingKey(61)); // smallest key >= 61
        System.out.println("higherKey(90): " + cutoffs.higherKey(90));   // none above 90 -> null
        System.out.println("headMap(70): " + cutoffs.headMap(70));       // keys < 70
        System.out.println("tailMap(80): " + cutoffs.tailMap(80));       // keys >= 80
    }
}

