#include <iostream>
#include <iterator>
#include <map>
#include <string>

// std::map is a red-black tree, the C++ counterpart of TreeMap
using Cutoffs = std::map<int, std::string>;

template <typename It>
std::string range(It from, It to) {
    std::string s = "{";
    for (auto it = from; it != to; ++it) s += (it == from ? "" : ", ") + std::to_string(it->first) + "=" + it->second;
    return s + "}";
}

int main() {
    Cutoffs cutoffs;
    cutoffs[80] = "B";
    cutoffs[0] = "F";
    cutoffs[90] = "A";
    cutoffs[60] = "D";
    cutoffs[70] = "C";
    std::cout << "cutoffs: " << range(cutoffs.begin(), cutoffs.end()) << "\n";
    std::cout << "firstKey: " << cutoffs.begin()->first << ", lastKey: " << cutoffs.rbegin()->first << "\n";

    for (int score : {59, 60, 85, 100}) {
        // floor = one step before the first key > score
        auto e = std::prev(cutoffs.upper_bound(score));
        std::cout << "score " << score << " -> floorKey " << e->first << " -> grade " << e->second << "\n";
    }

    std::cout << "ceilingKey(61): " << cutoffs.lower_bound(61)->first << "\n";
    auto higher = cutoffs.upper_bound(90);
    std::cout << "higherKey(90): " << (higher == cutoffs.end() ? "null" : std::to_string(higher->first)) << "\n";
    std::cout << "headMap(70): " << range(cutoffs.begin(), cutoffs.lower_bound(70)) << "\n";
    std::cout << "tailMap(80): " << range(cutoffs.lower_bound(80), cutoffs.end()) << "\n";
}

