// JS has no sorted map; keep sorted keys beside a Map and binary-search them.
const cutoffs = new Map([[80, 'B'], [0, 'F'], [90, 'A'], [60, 'D'], [70, 'C']]);
const keys = [...cutoffs.keys()].sort((a, b) => a - b);

// Index of the first key > x (upper bound) or >= x (lower bound)
const bound = (x, strict) => {
  let lo = 0;
  let hi = keys.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (strict ? keys[mid] <= x : keys[mid] < x) lo = mid + 1;
    else hi = mid;
  }
  return lo;
};
