import java.util.LinkedList;
import java.util.ListIterator;

public class LinkedListPlaylist {
    public static void main(String[] args) {
        // LinkedList is a doubly linked list: O(1) at both ends, O(n) to reach the middle
        LinkedList<String> playlist = new LinkedList<>();
        playlist.addLast("song-A");
        playlist.addLast("song-B");
        playlist.addLast("song-C");
        System.out.println("addLast x3:      " + playlist);

        playlist.addFirst("intro"); // relinks the head; nothing is shifted
        System.out.println("addFirst(intro): " + playlist);

        String playing = playlist.removeFirst(); // queue behaviour (FIFO)
        System.out.println("removeFirst():   " + playing + " -> " + playlist);

        String dropped = playlist.pollLast(); // stack/deque behaviour at the tail
        System.out.println("pollLast():      " + dropped + " -> " + playlist);

        // A ListIterator can insert at its current position in O(1) once it is there
        ListIterator<String> it = playlist.listIterator();
        while (it.hasNext()) {
            if (it.next().equals("song-A")) {
                it.add("ad-break"); // inserted right after song-A
            }
        }
        System.out.println("insert after A:  " + playlist);

        System.out.println("peekFirst: " + playlist.peekFirst() + ", peekLast: " + playlist.peekLast()
                + ", size: " + playlist.size());
    }
}

