// std::list is a doubly linked list, like Java's LinkedList
std::string show(const std::list<std::string>& l) {
    std::string s = "[";
    for (auto it = l.begin(); it != l.end(); ++it) s += (it == l.begin() ? "" : ", ") + *it;
    return s + "]";
}

int main() {
    std::list<std::string> playlist;
    playlist.push_back("song-A");
    playlist.push_back("song-B");
    playlist.push_back("song-C");
    std::cout << "addLast x3:      " << show(playlist) << "\n";

    playlist.push_front("intro");
    std::cout << "addFirst(intro): " << show(playlist) << "\n";

    std::string playing = playlist.front();
    playlist.pop_front();
    std::cout << "removeFirst():   " << playing << " -> " << show(playlist) << "\n";

    std::string dropped = playlist.back();
    playlist.pop_back();
    std::cout << "pollLast():      " << dropped << " -> " << show(playlist) << "\n";

    // insert() puts the new node before the given iterator, so step past song-A first
    auto it = std::find(playlist.begin(), playlist.end(), "song-A");
    if (it != playlist.end()) playlist.insert(std::next(it), "ad-break");
    std::cout << "insert after A:  " << show(playlist) << "\n";

    std::cout << "peekFirst: " << playlist.front() << ", peekLast: " << playlist.back()
              << ", size: " << playlist.size() << "\n";
}

