// JS has no built-in linked list, so here is a minimal doubly linked one.
class Node {
  constructor(value) {
    this.value = value;
    this.prev = null;
    this.next = null;
  }
}

class LinkedList {
  constructor() {
    this.head = null;
    this.tail = null;
    this.size = 0;
  }

  insertAfter(node, value) { // node === null means "insert at the front"
    const n = new Node(value);
    n.prev = node;
    n.next = node ? node.next : this.head;
    if (n.next) n.next.prev = n; else this.tail = n;
    if (node) node.next = n; else this.head = n;
    this.size += 1;
  }

  unlink(node) {
    if (node.prev) node.prev.next = node.next; else this.head = node.next;
    if (node.next) node.next.prev = node.prev; else this.tail = node.prev;
    this.size -= 1;
    return node.value;
  }

  addLast(v) { this.insertAfter(this.tail, v); }
  addFirst(v) { this.insertAfter(null, v); }
  removeFirst() { return this.unlink(this.head); }
  pollLast() { return this.tail ? this.unlink(this.tail) : null; }

  * [Symbol.iterator]() {
    for (let n = this.head; n; n = n.next) yield n;
  }

  toString() { return `[${[...this].map((n) => n.value).join(', ')}]`; }
}

const playlist = new LinkedList();
playlist.addLast('song-A');
playlist.addLast('song-B');
playlist.addLast('song-C');
console.log(`addLast x3:      ${playlist}`);

playlist.addFirst('intro');
console.log(`addFirst(intro): ${playlist}`);

const playing = playlist.removeFirst();
console.log(`removeFirst():   ${playing} -> ${playlist}`);

const dropped = playlist.pollLast();
console.log(`pollLast():      ${dropped} -> ${playlist}`);

// Walk to the node, then splice in a new one in O(1)
for (const node of playlist) {
  if (node.value === 'song-A') {
    playlist.insertAfter(node, 'ad-break');
    break;
  }
}
console.log(`insert after A:  ${playlist}`);

console.log(`peekFirst: ${playlist.head.value}, peekLast: ${playlist.tail.value}, size: ${playlist.size}`);

