import java.util.*;

public class IteratorSafeRemoval {
    public static void main(String[] args) {
        List<String> tasks = new ArrayList<>(List.of("read", "skip-quiz", "code", "skip-lab", "test"));
        System.out.println("start: " + tasks);

        // Wrong: for-each uses a hidden iterator; list.remove bumps modCount behind its back
        List<String> copy = new ArrayList<>(tasks);
        try {
            for (String t : copy) {
                if (t.startsWith("skip-")) {
                    copy.remove(t);
                }
            }
        } catch (ConcurrentModificationException e) {
            System.out.println("for-each + list.remove: ConcurrentModificationException");
        }

        // Right: remove through the iterator itself, which keeps its cursor consistent
        Iterator<String> it = tasks.iterator();
        while (it.hasNext()) {
            String t = it.next();
            if (t.startsWith("skip-")) {
                it.remove();
                System.out.println("iterator.remove() dropped " + t);
            }
        }
        System.out.println("after iterator pass: " + tasks);

        // Shortest: removeIf does the iterator loop for you
        List<Integer> nums = new ArrayList<>(List.of(1, 2, 3, 4, 5, 6));
        nums.removeIf(n -> n % 2 == 0);
        System.out.println("removeIf(even) on [1, 2, 3, 4, 5, 6]: " + nums);
    }
}

