#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

std::string show(const std::vector<std::string>& v) {
    std::string s = "[";
    for (size_t i = 0; i < v.size(); ++i) s += (i ? ", " : "") + v[i];
    return s + "]";
}

int main() {
    std::vector<std::string> tasks = {"read", "skip-quiz", "code", "skip-lab", "test"};
    std::cout << "start: " << show(tasks) << "\n";

    // Erasing inside a range-for invalidates its hidden iterator: undefined behavior in C++,
    // which is worse than Java's fail-fast exception, so we only report what Java would do.
    std::cout << "for-each + list.remove: ConcurrentModificationException\n";

    // Right: erase() returns an iterator to the next element; use it instead of ++it
    for (auto it = tasks.begin(); it != tasks.end();) {
        if (it->rfind("skip-", 0) == 0) {
            std::cout << "iterator.remove() dropped " << *it << "\n";
            it = tasks.erase(it);
        } else {
            ++it;
        }
    }
    std::cout << "after iterator pass: " << show(tasks) << "\n";

    // Shortest: the erase-remove idiom (std::erase_if in C++20) is C++'s removeIf
    std::vector<int> nums = {1, 2, 3, 4, 5, 6};
    nums.erase(std::remove_if(nums.begin(), nums.end(), [](int n) { return n % 2 == 0; }), nums.end());
    std::cout << "removeIf(even) on [1, 2, 3, 4, 5, 6]: [";
    for (size_t i = 0; i < nums.size(); ++i) std::cout << (i ? ", " : "") << nums[i];
    std::cout << "]\n";
}

