const show = (items) => `[${items.join(', ')}]`;

const tasks = ['read', 'skip-quiz', 'code', 'skip-lab', 'test'];
console.log(`start: ${show(tasks)}`);

// JS arrays do not fail fast: splicing inside for...of silently skips the next element.
// Java's ArrayList detects the same bug and throws instead.
console.log('for-each + list.remove: ConcurrentModificationException');

// Right: walk backwards with an index so a removal never shifts unvisited elements
const dropped = [];
for (let i = tasks.length - 1; i >= 0; i -= 1) {
  if (tasks[i].startsWith('skip-')) dropped.unshift(...tasks.splice(i, 1));
}
dropped.forEach((t) => console.log(`iterator.remove() dropped ${t}`));
console.log(`after iterator pass: ${show(tasks)}`);

// Shortest: filter builds a new array (JS's removeIf)
const nums = [1, 2, 3, 4, 5, 6].filter((n) => n % 2 !== 0);
console.log(`removeIf(even) on [1, 2, 3, 4, 5, 6]: ${show(nums)}`);

